def sets():
    out = []
    for lo, hi in ((1, 35), (36, 60), (61, 85), (86, 100)):
        qs = [(q, o, a, e + KEY, SRC.format(n)) for n in sorted(Q) if lo <= n <= hi for q, o, a, e in [Q[n]]]
        out.append({"name": f"Q{lo}–{hi}" + (" (Kannada)" if lo == 1 else ""), "questions": qs, "keep_order": True})
    return out


